// SellerGovernanceAdminServiceHandler is an implementation of the
// hawkr.admin.seller.v1alpha1.SellerGovernanceAdminService service.
type SellerGovernanceAdminServiceHandler interface {
	// ListReports 是通報的清單，可依處理狀態、生效的類別、店家與案件篩選。預設新到舊；state 是 AWAITING_TRIAGE 或指定 case_id 時依建立時間舊到新
	// （待分案與案件成員的處理順序）。清單的通報不帶 contact、evidence 與 supplements（GetReport 才有）。
	ListReports(context.Context, *connect.Request[v1alpha1.ListReportsRequest]) (*connect.Response[v1alpha1.ListReportsResponse], error)
	// GetReport 讀一筆通報，含補充、佐證與 etag；can_* 與 available_outcomes 是此刻能做的動作。
	GetReport(context.Context, *connect.Request[v1alpha1.GetReportRequest]) (*connect.Response[v1alpha1.GetReportResponse], error)
	// MarkReportSupplementsSeen 記下管理員看過這筆通報此刻的全部補充（通報頁顯示補充時呼叫；「有新的補充」的已讀標記，GetReport 本身不改任何狀態）。
	// etag 必填，必須是讀到補充時的 etag（補充讓通報的 etag 前進，所以相符就代表看過的是目前全部的補充；不符回 aborted（VERSION_CONFLICT），不記）。
	// 只改已看過的補充編號（supplements_seen_seq，不輸出）：**不讓 etag 前進**，所以不會讓別的分頁或對話框裡讀到的 etag 過時、也不會造成衝突。冪等：已經看過、沒有補充或已有結果的通報
	// 回成功、不寫入。權限是獨立的 seller.reports.mark_supplements_seen（adminauth 一支方法一個權限），目錄裡與 seller.reports.get 一起授予。
	MarkReportSupplementsSeen(context.Context, *connect.Request[v1alpha1.MarkReportSupplementsSeenRequest]) (*connect.Response[v1alpha1.MarkReportSupplementsSeenResponse], error)
	// TriageReport 分案：判定平台判定類別，把通報掛到這家店那個類別進行中的案件；沒有進行中的案件就開一個，開新案件必須給嚴重度，
	// 加入進行中的案件不可以給（嚴重度以案件為準）。只有還沒有案件也沒有結果的通報可以。etag 必填。
	TriageReport(context.Context, *connect.Request[v1alpha1.TriageReportRequest]) (*connect.Response[v1alpha1.TriageReportResponse], error)
	// ResolveReport 設定通報的結果（已採取措施、未違規、內容不足、重複、濫報），結果設定後不能修改。已採取措施只能設在案件裡的通報，而且案件要有
	// 導出的措施或已有成員的結果是已採取措施；還沒分案的通報可以直接設定其他四個結果。etag 必填。
	ResolveReport(context.Context, *connect.Request[v1alpha1.ResolveReportRequest]) (*connect.Response[v1alpha1.ResolveReportResponse], error)
	// MoveReport 改通報的平台判定類別，通報移到這家店那個類別的案件（沒有進行中的就開一個）。只有進行中案件裡、還沒有結果、不是認定來源的通報
	// 可以；案件有導出的措施時最後一筆不能移走。移走最後一筆時原案件以 NO_REPORTS 自動關閉，不算一次決定。etag 必填。
	MoveReport(context.Context, *connect.Request[v1alpha1.MoveReportRequest]) (*connect.Response[v1alpha1.MoveReportResponse], error)
	// ListCases 列出案件，開案時間新到舊。
	ListCases(context.Context, *connect.Request[v1alpha1.ListCasesRequest]) (*connect.Response[v1alpha1.ListCasesResponse], error)
	// GetCase 讀一個案件，含移動紀錄與 etag；can_* 與 decision_options 是此刻能做的動作。
	GetCase(context.Context, *connect.Request[v1alpha1.GetCaseRequest]) (*connect.Response[v1alpha1.GetCaseResponse], error)
	// DecideCase 決定案件（採取措施或不採取措施），決定即結案，結案是終態。結案時還沒有結果的通報帶入決定的預設結果與給檢舉人的說明。
	// 還沒結束的詢問在同一個 transaction 由系統撤回（withdraw_cause 是 CASE_CLOSED）。
	// decision 必須在案件的 decision_options 裡。etag 必填。
	DecideCase(context.Context, *connect.Request[v1alpha1.DecideCaseRequest]) (*connect.Response[v1alpha1.DecideCaseResponse], error)
	// ChangeCaseSeverity 修改案件的嚴重度，必須附原因：原因寫成案件的一則內部註記，改前改後記在那則註記上。只限進行中的案件。etag 必填。
	ChangeCaseSeverity(context.Context, *connect.Request[v1alpha1.ChangeCaseSeverityRequest]) (*connect.Response[v1alpha1.ChangeCaseSeverityResponse], error)
	// CreateCaseInquiry 對案件的賣家發一筆詢問（提供紀錄或請說明，有期限；詢問只帶管理員轉述的說明，不附通報原文、佐證與檢舉人）。每個案件同時最多
	// 一筆還沒結束的詢問；案件結案後、店家的個資已依保留期限清除後不能發（關店不擋）。建立讓案件的 etag 前進，案件進入「等賣家」（awaiting_seller），
	// 不在「待決定」。不帶 etag；request_id 選填（AIP-155）：同一位管理員以同一個 request_id 重送，回傳原本那一筆，內容不同回 invalid_argument。
	// 賣家端的畫面上線（10f）之前，系統不會通知賣家，請管理員另外聯絡。
	CreateCaseInquiry(context.Context, *connect.Request[v1alpha1.CreateCaseInquiryRequest]) (*connect.Response[v1alpha1.CreateCaseInquiryResponse], error)
	// ListCaseInquiries 列出案件的詢問，舊到新。案件不存在回 not_found。
	ListCaseInquiries(context.Context, *connect.Request[v1alpha1.ListCaseInquiriesRequest]) (*connect.Response[v1alpha1.ListCaseInquiriesResponse], error)
	// RecordCaseInquiryReply 記下系統外收到的賣家回覆（管道、收到的時間、內容與最多 5 份附件），記下之後這筆詢問就結束；要再問，另發一筆詢問。
	// 收到的時間不早於詢問建立、不晚於現在；案件的「待決定」從這個時間重新起算。附件是機敏檔（先以機敏上傳取得 staged token）。已經記過時回原本那一則
	// （already_recorded）；詢問已撤回回 failed_precondition。不帶 etag。
	RecordCaseInquiryReply(context.Context, *connect.Request[v1alpha1.RecordCaseInquiryReplyRequest]) (*connect.Response[v1alpha1.RecordCaseInquiryReplyResponse], error)
	// WithdrawCaseInquiry 撤回還沒回覆的詢問（賣家不必再回覆）。案件因決定或通報都移走而結案時，還沒結束的詢問由系統撤回（withdraw_cause 是 CASE_CLOSED）。
	// 已經撤回時回 already_withdrawn；已回覆回 failed_precondition。不帶 etag。
	WithdrawCaseInquiry(context.Context, *connect.Request[v1alpha1.WithdrawCaseInquiryRequest]) (*connect.Response[v1alpha1.WithdrawCaseInquiryResponse], error)
	// CreateAuthorityOrder 登記主管機關的一份來函（機關、文號、收文時間、種類、內容摘要、指名的對象、期限）。來函是獨立的收件，不是通報。
	// 對象是任何帳號（帳號必須存在），選填店家（必須屬於帳號）與商品；整個帳號加上它的店家是重疊，invalid_argument。登記時保存期限定為收文後 184 天：
	// 指名的帳號或店家在 seller 的個資在這之前不會被關店後的清理刪除（不影響恢復營業）；帳號在 seller 沒有店家時照樣登記，no_seller_data 為 true。
	// 不帶 etag；request_id 選填（AIP-155），範圍是（登記的管理員, request_id）。
	CreateAuthorityOrder(context.Context, *connect.Request[v1alpha1.CreateAuthorityOrderRequest]) (*connect.Response[v1alpha1.CreateAuthorityOrderResponse], error)
	// ListAuthorityOrders 列出來函：OPEN 依期限舊到新，其餘依收文時間新到舊；可依狀態與指名的帳號篩選。
	ListAuthorityOrders(context.Context, *connect.Request[v1alpha1.ListAuthorityOrdersRequest]) (*connect.Response[v1alpha1.ListAuthorityOrdersResponse], error)
	// GetAuthorityOrder 讀一份來函，含對象逐家的涵蓋狀態、告知與保存期限的延長歷史。
	GetAuthorityOrder(context.Context, *connect.Request[v1alpha1.GetAuthorityOrderRequest]) (*connect.Response[v1alpha1.GetAuthorityOrderResponse], error)
	// CompleteAuthorityOrder 標記來函完成並寫處理摘要，同時記下每個對象的告知。調取資料的來函可以帶 provide_time，保存期限延到「提供之後 184 天」
	// （取收文與提供兩者較晚的）。完成不解除保存。etag 必填。
	CompleteAuthorityOrder(context.Context, *connect.Request[v1alpha1.CompleteAuthorityOrderRequest]) (*connect.Response[v1alpha1.CompleteAuthorityOrderResponse], error)
	// ExtendAuthorityOrderHold 延長保存期限（只能延長，新值必須晚於目前），每次延長留下前後值、原因與管理員。已完成或已到期的來函也能延長。etag 必填。
	ExtendAuthorityOrderHold(context.Context, *connect.Request[v1alpha1.ExtendAuthorityOrderHoldRequest]) (*connect.Response[v1alpha1.ExtendAuthorityOrderHoldResponse], error)
	// RecordAuthorityTargetNotice 記下一個暫不告知（WITHHELD）的對象後來的告知：改成已告知，或寫新的確認日期（每次改變留歷史）。etag 必填。
	RecordAuthorityTargetNotice(context.Context, *connect.Request[v1alpha1.RecordAuthorityTargetNoticeRequest]) (*connect.Response[v1alpha1.RecordAuthorityTargetNoticeResponse], error)
	// RevokeAuthorityOrder 撤銷登記錯誤的來函（例如對象或文號登記錯了）：只在還沒完成時可以（can_revoke），必須附原因。撤銷之後來函的保存解除（不再擋個資清理）、
	// 不再是處理中，也不能再當作措施的來源；紀錄保留（撤銷的時間、管理員與原因）。正確的來函另外登記。etag 必填；同一位管理員重送（已由他撤銷）回傳原本的結果
	// （already_revoked），不比較 etag 與原因；已由別的管理員撤銷或已完成回 failed_precondition。
	RevokeAuthorityOrder(context.Context, *connect.Request[v1alpha1.RevokeAuthorityOrderRequest]) (*connect.Response[v1alpha1.RevokeAuthorityOrderResponse], error)
	// CreateMeasure 建立一個措施。措施的種類就是設定的是哪一支輸入（warning、suspension 或 termination，沒有另外的種類欄位）：
	// 警告依據違規的認定；停權依據違規的認定（VIOLATION，必填 end_time）或條款第 17.1、17.5 條的風險類型（RISK，必填 review_by）；
	// 終止合作依據條款第 21.2、21.3 條的事由（依據由伺服器依事由推導）。停權在同一個 transaction 讓帳號立即停權；店家必須還沒關閉
	// （非預告的終止合作可以建在帳號沒有目前店家的最近一個 stint 上，效果只剩禁止入駐）；店家已關閉而不能建立時回 failed_precondition，
	// 訊息與 GetStoreResponse.create_measure_unavailabilities 的第一句相同。
	// 終止合作：NOTICE 建立後 30 日生效（SCHEDULED，期間店家照常營業），其餘事由立即生效、店家暫停營業；生效中的終止在沒有未結訂單時關店
	// （背景工作，closed_by 是 TERMINATION）。終止不接受 end_time 與 review_by。RISK 必填 review_by，落在現在之後、
	// 30 天以內。來源通報必須是同一家店、而且結果不是未違規、內容不足或濫報（Report.can_cite_as_source）。從案件建立時帶 source_case_id：任何種類與依據都可以，
	// 之後這個措施算是案件導出的措施。升級規則：帳號 90 天內第 3 次 MEDIUM 升為 HIGH（認定的 severity
	// 是套用的，escalated_from 是原本的）。同一個 transaction 寫入第 1 版與第一則內部註記（note 必填）。request_id 選填：同一位
	// 管理員帶同一個 request_id、同樣的內容重送，回傳原本的措施（目前的狀態）；內容不同回 invalid_argument。
	CreateMeasure(context.Context, *connect.Request[v1alpha1.CreateMeasureRequest]) (*connect.Response[v1alpha1.CreateMeasureResponse], error)
	// GetMeasure 讀一筆措施，含全部版本（revisions，舊到新）、依據的認定與申覆的佐證。內部註記不內嵌，用 ListMeasureNotes 讀。
	GetMeasure(context.Context, *connect.Request[v1alpha1.GetMeasureRequest]) (*connect.Response[v1alpha1.GetMeasureResponse], error)
	// ListMeasures 列出措施，新到舊。收件匣的排序，優先序是 review_due 是 true 時依 review_by 舊到新，其次 request_state 是 PENDING
	// 時依請求（申覆與解除請求合在同一個收件匣）提出時間舊到新；篩選條件可以組合，其餘條件都是 AND。
	// 清單的措施不帶請求的佐證與 revisions（GetMeasure 才有）。source_case_id 只列某個案件導出的措施，source_report_id 只列依據的認定以某筆通報為來源的措施。
	ListMeasures(context.Context, *connect.Request[v1alpha1.ListMeasuresRequest]) (*connect.Response[v1alpha1.ListMeasuresResponse], error)
	// UpdateMeasure 修改措施賣家看得到的 statement 與 end_time（update_mask），其他欄位都是 OUTPUT_ONLY。etag 必填。實際改了
	// 就產生新的一版（revisions）並讓 etag 改變。end_time 必須晚於現在；比目前晚是延長、比目前早是縮短；只有生效中（ACTIVE）的
	// 停權可以延長或縮短，警告不能設 end_time，VIOLATION 依據不能清除 end_time；終止合作不接受 end_time（要延後生效請撤銷後重建），statement
	// 在預定生效與生效中都可以改。提出申覆起措施凍結：不能改 statement、不能延長
	// （failed_precondition，不帶欄位），只能縮短。沒有任何欄位改變時不寫入，etag 不變。
	UpdateMeasure(context.Context, *connect.Request[v1alpha1.UpdateMeasureRequest]) (*connect.Response[v1alpha1.UpdateMeasureResponse], error)
	// EndMeasure 結束 RISK 措施（風險已排除）：寫一版 end_time = 現在。只限生效中的 RISK 停權；VIOLATION 依據的措施要縮短期間或
	// 撤銷。etag 必填。
	EndMeasure(context.Context, *connect.Request[v1alpha1.EndMeasureRequest]) (*connect.Response[v1alpha1.EndMeasureResponse], error)
	// RevokeMeasure 撤銷措施並在同一個 transaction 解除它的效果。etag 必填。申覆待裁定時回 failed_precondition（先裁定申覆）；
	// 已撤銷的回 failed_precondition。revoke_findings 為 true 時撤銷這個措施自己建立的認定，並連帶撤銷引用那些認定的其他措施
	// （原因 FINDING_REVOKED，待處理的請求以 CLOSED 結案）；只在措施的 can_revoke_findings 為 true 時可以設（否則回 invalid_argument）。reason 不可以是 APPEAL_ACCEPTED、
	// FINDING_REVOKED 或 SOURCE_REVOKED。撤銷終止合作：同一個 transaction 恢復同一個店家的條件是，店家是因終止合作而關閉的、造成關店的那一筆（在這次撤銷之後）已撤銷、
	// 撤銷之後帳號沒有仍生效中的終止（預定生效的預告不算）、還沒到保留期（關店後 184 天，與帳號上未撤銷的終止的最晚申覆期限〔生效後 184 天〕，取較晚者）而且沒有被個資清理；
	// 帳號已另開新店則只撤銷。不符合時只撤銷紀錄與禁止入駐（例如先撤銷造成關店的那一筆、帳號另有生效中的終止時店家仍關閉，等最後一筆也撤銷才恢復）。撤銷來源終止時，以它為來源的關聯終止在同一個
	// transaction 一併撤銷（SOURCE_REVOKED）。etag 與目前的版本不符一律回 aborted（VERSION_CONFLICT），不寫入。
	RevokeMeasure(context.Context, *connect.Request[v1alpha1.RevokeMeasureRequest]) (*connect.Response[v1alpha1.RevokeMeasureResponse], error)
	// ScheduleMeasureReview 重新排定 RISK 措施的複審期限（落在現在之後、30 天以內），並在同一個 transaction 寫一則內部註記（note
	// 必填）。只限生效中的 RISK 停權。後台的 etag 改變、賣家的 etag 不變。
	ScheduleMeasureReview(context.Context, *connect.Request[v1alpha1.ScheduleMeasureReviewRequest]) (*connect.Response[v1alpha1.ScheduleMeasureReviewResponse], error)
	// DecideAppeal 裁定措施的申覆：ACCEPTED 在同一個 transaction 撤銷措施並解除效果（revoke_findings 為 true 時一併撤銷認定；終止合作的
	// 恢復店家與關聯終止的連帶撤銷同 RevokeMeasure）；終止合作期滿前提出的申覆，期滿後仍可裁定；
	// REJECTED 措施不變。兩者都必須附理由，賣家看得到。只有待處理的申覆可以。etag 必填；etag 不符（包含裁定已經生效後再帶舊
	// etag 送一次）一律回 aborted（VERSION_CONFLICT），不寫入。
	DecideAppeal(context.Context, *connect.Request[v1alpha1.DecideAppealRequest]) (*connect.Response[v1alpha1.DecideAppealResponse], error)
	// DecideRemediation 裁定措施待處理的解除請求（賣家依條款第 17.4 條檢具事證請求解除，RISK 依據）：ACCEPTED 在同一個 transaction 寫一版
	// end_time = 現在（作者是裁定的管理員、statement 不變）並重算停權狀態，措施 state 變 ENDED；這不是撤銷，認定與撤銷原因都不動，
	// 賣家仍可申覆；REJECTED 措施不變，計入冷卻（Measure.next_remediation_time）。兩者都必須附理由，賣家看得到。只有措施生效中而且
	// 有待處理的解除請求時可以（can_decide_remediation）。不帶 request_id：同一措施同時最多一筆待處理請求，etag 保證裁定的是管理員看到的
	// 那一筆。etag 必填；ACCEPTED 寫新的一版，賣家與後台的 etag 都變；REJECTED 只改變後台的 etag。etag 不符（包含裁定已經生效後再帶舊
	// etag 送一次）一律回 aborted（VERSION_CONFLICT），不寫入。
	DecideRemediation(context.Context, *connect.Request[v1alpha1.DecideRemediationRequest]) (*connect.Response[v1alpha1.DecideRemediationResponse], error)
	// CreateMeasureNote 在措施的內部註記時間軸新增一則。註記只新增，不能改也不能刪，更正就再寫一則；不帶 etag，也不改措施的
	// 任何 etag（註記不是賣家看得到的內容，賣家依舊 etag 的申覆不受影響）。已撤銷或已申覆的措施都可以寫。
	CreateMeasureNote(context.Context, *connect.Request[v1alpha1.CreateMeasureNoteRequest]) (*connect.Response[v1alpha1.CreateMeasureNoteResponse], error)
	// ListMeasureNotes 列出措施的內部註記，舊到新。註記是只新增、不經 etag 的子集合，所以不內嵌在 Measure，獨立分頁讀取。措施
	// 不存在回 not_found。
	ListMeasureNotes(context.Context, *connect.Request[v1alpha1.ListMeasureNotesRequest]) (*connect.Response[v1alpha1.ListMeasureNotesResponse], error)
	// CreateCaseNote 在案件的內部註記時間軸新增一則，規則同 CreateMeasureNote：只新增、不帶 etag、不改案件的 etag，已結案的案件也可以寫；案件不存在回 not_found。
	// note.severity_change 只由 ChangeCaseSeverity 寫入，這裡不採用。
	CreateCaseNote(context.Context, *connect.Request[v1alpha1.CreateCaseNoteRequest]) (*connect.Response[v1alpha1.CreateCaseNoteResponse], error)
	// ListCaseNotes 列出案件的內部註記，舊到新（含改嚴重度時寫的那幾則）。案件不存在回 not_found。
	ListCaseNotes(context.Context, *connect.Request[v1alpha1.ListCaseNotesRequest]) (*connect.Response[v1alpha1.ListCaseNotesResponse], error)
	// GetViolation 讀一筆認定（只讀）。
	GetViolation(context.Context, *connect.Request[v1alpha1.GetViolationRequest]) (*connect.Response[v1alpha1.GetViolationResponse], error)
	// ListViolations 列出認定，新到舊。認定只由 CreateMeasure 建立。
	ListViolations(context.Context, *connect.Request[v1alpha1.ListViolationsRequest]) (*connect.Response[v1alpha1.ListViolationsResponse], error)
}

